import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Sequence, Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model': 256, 'num_blocks': 5,
        'dilations': [1,2,4,8,16], 'kernel_size': 7, 'dropout_rate': 0.1,
        'tau': 0.25,
        'transformer_layers': 4, 'num_heads': 4, 'transformer_ff_dim': 512
    }

# --- Shared Backbone ---
class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int; dilation: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h=nn.LayerNorm()(x); h=nn.Conv(self.d_model,(self.kernel_size,),feature_group_count=self.d_model,padding='SAME',kernel_dilation=(self.dilation,))(h); h=nn.gelu(h); h=nn.Conv(self.d_model,(1,))(h); h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic); return x+h

class DSConvFeatureExtractor(nn.Module):
    d_model: int; num_blocks: int; dilations: Sequence[int]; kernel_size: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h=nn.Dense(self.d_model)(x); h=nn.gelu(h); h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic)
        for i in range(self.num_blocks):
            h=DSConvDilatedBlock(self.d_model,self.kernel_size,self.dilations[i],self.dropout_rate)(h,deterministic=deterministic)
        return h

# --- Expert Components ---
def lse_pool(h, tau):
    x=h/tau; m=jnp.max(x,axis=1,keepdims=True); return tau*(jnp.log(jnp.mean(jnp.exp(x-m),axis=1)+1e-12)+jnp.squeeze(m,axis=1))

class AddPositionalEncodings(nn.Module):
    d_model: int
    @nn.compact
    def __call__(self, x):
        pe=jnp.zeros((x.shape[1],self.d_model)); p=jnp.arange(0,x.shape[1])[:,None]; d=jnp.exp(jnp.arange(0,self.d_model,2)*-(jnp.log(10000.0)/self.d_model)); pe=pe.at[:,0::2].set(jnp.sin(p*d)); pe=pe.at[:,1::2].set(jnp.cos(p*d)); return x+pe[None,:,:]

class TransformerEncoderBlock(nn.Module):
    d_model: int; num_heads: int; ff_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h=nn.LayerNorm()(x); h=nn.MultiHeadDotProductAttention(self.num_heads, qkv_features=self.d_model, dropout_rate=self.dropout_rate)(h,deterministic=deterministic); x=x+nn.Dropout(self.dropout_rate)(h,deterministic=deterministic)
        h=nn.LayerNorm()(x); h=nn.Dense(self.ff_dim)(h); h=nn.gelu(h); h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic); h=nn.Dense(self.d_model)(h); x=x+nn.Dropout(self.dropout_rate)(h,deterministic=deterministic); return x

# --- Main Architecture ---
class AveragedMoEv2(nn.Module):
    d_output: int; task_type: str; d_model: int; num_blocks: int; dilations: Sequence[int]
    kernel_size: int; dropout_rate: float; tau: float; transformer_layers: int; num_heads: int; transformer_ff_dim: int
    @nn.compact
    def __call__(self, x, deterministic=True):
        features_seq = DSConvFeatureExtractor(self.d_model,self.num_blocks,self.dilations,self.kernel_size,self.dropout_rate)(x,deterministic=deterministic)

        # Expert A: Pooling
        mean_vec=jnp.mean(features_seq,axis=1); lse_vec=lse_pool(features_seq,self.tau); pooled_vec=jnp.concatenate([mean_vec,lse_vec],axis=-1)

        # Expert B: Transformer
        cls_token=self.param('cls',nn.initializers.zeros,(1,1,self.d_model)); cls_token=jnp.tile(cls_token,(features_seq.shape[0],1,1))
        trans_in=jnp.concatenate([cls_token,features_seq],axis=1)
        trans_in=AddPositionalEncodings(self.d_model)(trans_in)
        h=nn.Dropout(self.dropout_rate)(trans_in,deterministic=deterministic)
        for _ in range(self.transformer_layers):
            h=TransformerEncoderBlock(self.d_model,self.num_heads,self.transformer_ff_dim,self.dropout_rate)(h,deterministic=deterministic)
        trans_vec = h[:, 0]

        d_expert = self.d_model * 2
        pooled_vec_proj = nn.Dense(d_expert)(pooled_vec)
        trans_vec_proj = nn.Dense(d_expert)(trans_vec)

        fused = 0.5 * pooled_vec_proj + 0.5 * trans_vec_proj

        z=nn.LayerNorm()(fused); z=nn.Dense(self.d_model)(z); z=nn.gelu(z); z=nn.Dropout(self.dropout_rate)(z,deterministic=deterministic)
        logits=nn.Dense(self.d_output)(z)
        return logits.squeeze(-1) if self.task_type=='regression' and self.d_output==1 else logits

class NetworkWrapper:
    def __init__(self, m): self.network = m
    def init(self, r, d): p, dr = random.split(r); return self.network.init({'params': p, 'dropout': dr}, d, deterministic=True)
    def apply(self, p, x, deterministic=True, rng_key=None):
        if rng_key is None: rng_key=random.PRNGKey(0)
        return self.network.apply(p, x, deterministic=deterministic, rngs={'dropout': rng_key})

def create_network(hparams):
    return NetworkWrapper(AveragedMoEv2(**{k: v for k, v in hparams.items() if k in AveragedMoEv2.__annotations__}))
